import bcrypt
from flask import (flash,
                   g,
                   redirect,
                   render_template,
                   request,
                   url_for)
from flask_login import login_required

from application import app, db, lm
from config import WEBHOME, admin_group_name
from .models import User, Group
from .forms import RegisterForm
from .forms_admin import AddGroupForm, EditUserForm, EnterPasswordForm
from .views_main import admin_permission


@app.route(WEBHOME + 'admin')
@login_required
@admin_permission.require(http_exception=403)
def admin():
    return render_template('admin.html', title='Admin')


@app.route(WEBHOME + 'add_user', methods=['GET', 'POST'])
@login_required
@admin_permission.require(http_exception=403)
def add_user():
    form = RegisterForm()
    if form.validate_on_submit():
        password = form.password.data
        password = password.encode('utf-8')
        password = bcrypt.hashpw(password, bcrypt.gensalt())
        register = User(username=form.username.data,
                        email=form.email.data,
                        name=form.name.data,
                        password=password)
        db.session.add(register)
        db.session.commit()
        flash('You have succesfully registered new user {}.'.format(form.username.data))
        return redirect(url_for('admin_users'))
    return render_template('admin_add_user.html', title='Add User', form=form)


