@Injectable()
export class Izanagi {
  constructor(public http: Http) {}

  setStreamLink(episode: any) {
    return new Promise((resolve, reject) => {
      this.http
        .get(episode.streamLink)
        .map(res => res.json())
        .subscribe(item => {
          episode.streamLink = item.file.replace('\\','');
          resolve(episode);
        },
        err => reject(err));
    });
  }

}

